    'UI_STRATEGY_FULL_TOOLTIPS' => "Vollständige Sicherung führt eine Sicherungsleistung für alle Sicherungsquelldaten aus. ",
    'UI_STRATEGY_INCR_TOOLTIPS' => " Eine Teilsicherung ist ein gängiger Sicherungstyp, der nur Daten sichert, die seit der letzten Sicherung erstellt oder geändert wurden. ",
    'UI_STRATEGY_DIFF_TOOLTIPS' => " Eine differenzielle Sicherung ist eine Art von Datensicherung, bei der Daten erhalten bleiben und nur die Unterschiede zwischen den Daten seit der letzten vollständigen Sicherung gespeichert werden. ",
    'UI_STRATEGY_PINCR_TOOLTIPS' => "永久增量为，在做备份任务时，只需做一次完全备份，以后只做增量备份。永久增量只做一次完全备份，减少完全备份次数，节省备份存储空间及带宽资源",
    'UI_STRATEGY_THREE_TOOLTIPS' => "Im Allgemeinen empfehlen wir, wöchentlich/monatlich eine vollständige Sicherung und täglich eine inkrementelle Sicherung durchzuführen. Inkrementelle Sicherung und differenzielle Sicherung können nicht gleichzeitig ausgewählt werden. Wenn Sie nur inkrementelle Sicherung oder differenzielle Sicherung auswählen, wird der erste aktivierte Sicherungsjob auf vollständige Sicherung herabgesetzt. ",
    'UI_STRATEGY_LOG_TOOLTIPS_MYSQL' => "日志备份是在上一次日志备份或完全备份的基础上,对比变化的日志数据",
    'UI_STRATEGY_LOG_TOOLTIPS_SQLSERVER' => "日志备份是在上一次备份的基础上,对变化的日志数据进行备份,依赖于上一个日志时间点或增加时间点或差异时间点或完备时间点",
    'UI_STRATEGY_LOG_TOOLTIPS_ORACLE' => "归档日志备份是对最近给定天数的日志数据进行备份",
    'UI_STRATEGY_LOG_TOOLTIPS_DM' => "归档日志备份是对上一次备份后产生的所有日志数据进行备份,依赖于上一次备份时间点",
    'UI_STRATEGY_ROLL_NO' => "不滚动",
