    'UI_BACKUP_DATA_RESERVE_TYPE' => "Aufbewahrungsmodus ",
    'UI_BACKUP_DATA_DES' => "  Sicherungsziel ",
    'UI_BACKUP_DATA_DES_TIPS' => "Der Ort, an dem die Sicherungsdaten gespeichert werden ",
    'UI_BACKUP_AUTO_NODE' => "Knoten automatisch auswählen",
    'UI_BACKUP_AUTO_NODE_TIPS' => "'EIN': Das System wählt automatisch einen Sicherungsknoten aus, auf dem die Daten gespeichert werden sollen. 'AUS': Manuelles Auswählen eines Sicherungsknotens.",
    'UI_BACKUP_DIY_NODE' => "Benutzerdefinierte Auswahl",
    'UI_BACKUP_AUTO_STORAGE' => "Speicher automatisch auswählen",
    'UI_BACKUP_AUTO_STORAGE_TIPS' => "'EIN': Das System wählt automatisch einen optimalen Speicher aus, der auf dem ausgewählten Sicherungsknoten installiert ist. 'AUS': Manuelles Auswählen eines Speichers.",
    'UI_BACKUP_DIY_STORAGE' => "Benutzerdefinierte Auswahl",
    'UI_BACKUP_STORAGE_TIPS' => "Optionen für Datendeduplizierung und -komprimierung",
    'UI_BACKUP_TRANSPORT_TIPS' => "Optionen für das Datenübertragungsnetz",
    'UI_BACKUP_TRANSPORT_MODE' => "Transfer über ",
    'UI_BACKUP_TRANSPORT_NBD' => "LAN ",
    'UI_BACKUP_TRANSPORT_NBD_XENSERVER' => "NBD",
    'UI_BACKUP_TRANSPORT_NBD_SAN_XENSERVER' => "SAN+NBD",
    'UI_BACKUP_TRANSPORT_NBDSSL' => "Datenverschlüsselung ",
    'UI_BACKUP_TRANSPORT_SAN' => "SAN (LAN-Free)",
    'UI_BACKUP_TRANSPORT_HOT' => "HOTADD (LAN-Free)",
    'UI_BACKUP_TRANSPORT_HOT_VMWARE' => "HOTADD",
    'UI_BACKUP_TRANSPORT_SELECT_TIPS' => "LAN: Sicherungsdaten, die über LAN vom Produktionsarbeitsbereich in den Sicherungsbereich übertragen werden sollen. <br> <br> SAN (LAN-frei): Sicherungsdaten, die über SAN vom Produktionsspeicherbereich in den Sicherungsbereich übertragen werden sollen. Für die Übertragung über SAN (LAN-frei) müssen Sie zuerst einen LAN-freien Pfad aus den 'LAN-freien Einstellungen' hinzufügen. <br> <br> Datenverschlüsselung: Wenn Daten über LAN übertragen werden, wird die Übertragung mit SSL verschlüsselt Daten. <br> <br> HOTADD (LAN-frei): Verwenden Sie die Hot-Add-Funktion für VMware-Festplatten, um die Ziel-VM-Festplatte zum Lesen und Schreiben von Daten an den Vinchin Backup-Server anzuhängen. <br> <br> Wenn keine SAN-Übertragung verfügbar ist, System schaltet automatisch auf LAN-Übertragung um. ",
    'UI_BACKUP_TRANSPORT_VMWARE_SELECT_TIPS' => "LAN: Sicherungsdaten, die über LAN vom Produktionsarbeitsbereich in den Sicherungsbereich übertragen werden sollen. <br> <br> SAN (LAN-frei): Sicherungsdaten, die über SAN vom Produktionsspeicherbereich in den Sicherungsbereich übertragen werden sollen. Für die Übertragung über SAN (LAN-frei) müssen Sie zuerst einen LAN-freien Pfad aus den 'LAN-freien Einstellungen' hinzufügen. <br> <br> Datenverschlüsselung: Wenn Daten über LAN übertragen werden, wird die Übertragung mit SSL verschlüsselt Daten. <br> <br> HOTADD: 通过ESXI的SCSI HotAdd特性将目标磁盘挂载到备份服务器/代理上，实现数据的直接访问<br> <br> Wenn keine SAN-Übertragung verfügbar ist, System schaltet automatisch auf LAN-Übertragung um. ",
    'UI_BACKUP_TRANSPORT_ICS_VVDK_SELECT_TIPS' => "LAN: Sicherungsdaten, die über LAN vom Produktionsarbeitsbereich in den Sicherungsbereich übertragen werden sollen. ",
    'UI_BACKUP_TRANSPORT_SELECT_NBD_TIPS' => '【网络会自动切换，若有专用备份网络则优先使用专用网络传输，否则才会切换至管理网络进行传输】',
    'UI_BACKUP_TRANSPORT_HUAWEI_KVM_SELECT_TIPS' => "NBD传输:通过虚拟化平台提供的接口将备份数据传输到备份存储介质",
    'UI_BACKUP_TRANSPORT_RHV_SELECT_TIPS' => "网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br><br>ImageIO传输:通过虚拟化平台提供的接口将备份数据传输到备份存储介质",
    'UI_BACKUP_TRANSPORT_HUAWEI_SELECT_TIPS' => "LAN: Daten, die über LAN vom Produktionsarbeitsbereich in den Sicherungsbereich übertragen werden sollen. <br> <br> SAN (LAN-frei): Sicherungsdaten, die über SAN vom Produktionsspeicherbereich in den Sicherungsbereich übertragen werden sollen. Zum Übertragen über SAN (LAN-frei) müssen Sie zuerst einen LAN-freien Pfad aus den 'LAN-freien Einstellungen' hinzufügen. <br> <br> Datenverschlüsselung: Die über SSL verschlüsselten Sicherungsdaten. <br> <br> Wenn SAN Übertragung ist nicht verfügbar, das System wechselt automatisch zur LAN-Übertragung. ",
    'UI_BACKUP_TRANSPORT_LEIXEN_SELECT_TIPS' => "LAN:Daten, die über LAN vom Produktionsarbeitsbereich in den Sicherungsbereich übertragen werden sollen. <br> <br> SAN (LAN-frei): Sicherungsdaten, die über SAN vom Produktionsspeicherbereich in den Sicherungsbereich übertragen werden sollen. Um über SAN (LAN-frei) zu übertragen, müssen Sie zuerst einen LAN-freien Pfad aus den LAN-freien Einstellungen hinzufügen. <br> <br> Wenn keine SAN-Übertragung verfügbar ist, wechselt das System automatisch zur LAN-Übertragung. ",
    'UI_BACKUP_TRANSPORT_XENSERVER_SELECT_TIPS' => "网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br><br>NBD传输:通过虚拟化平台提供的接口将备份数据传输到备份存储介质,XenServer7.3及以上支持<br><br>SAN+NBD传输:备份数据通过NBD方式SAN传输到备份存储<br><br>如果SAN传输未生效,会自动使用网络传输",
    'UI_BACKUP_TRANSPORT_HOTADD' => "HotAdd Übertragung ",
    'UI_BACKUP_DATA_RESERVE_TYPE_TIPS' => "Aufbewahrungsrichtlinie für Sicherungsdaten ",
    'UI_BACKUP_MODE' => "Erweiterter Sicherungsmodus",
    'UI_BACKUP_MODE_TIPS' => "Erweiterte Optionen zum einfacheren Sichern ",
    'UI_BACKUP_MODE_HIGH_SPEED' => "SpeedKit ",
    'UI_BACKUP_MODE_HIGH_SPEED_TIPS' => "SpeedKit kann dazu beitragen, die Rechengeschwindigkeit geänderter Blöcke bei inkrementellen Sicherungen zu verbessern. Es wird empfohlen, diese Option zu aktivieren, wenn Sie eine schnellere Sicherung wünschen. (Voraussetzung: Ihr Stauraum ist groß genug.) <br><br>SpeedKit does not support Proxy.",
    'UI_BACKUP_INC_MODE_TIPS' => "高速：备份完成后会保留一个快照,加快定位有效数据的速度<br><br>CBT：不保留任何快照,通过变化块跟踪技术计算有效数据<br><br>普通：不保留任何快照,在备份任务前需要更多时间计算有效数据",
    'UI_BACKUP_INC_MODE_TIPS_EN' => "SpeedKit ist eine Vinchin-Technologie zur Verbesserung der Rechengeschwindigkeit geänderter Blöcke bei inkrementellen Sicherungen. Es wird empfohlen, diese Option auszuwählen, wenn Sie eine schnellere Sicherung wünschen oder wenn CBT nicht funktioniert. (Voraussetzung: Stellen Sie sicher, dass Ihr Speicherplatz groß genug ist.) <br> <br> CBT ist eine Citrix-Technologie, die die Geschwindigkeit inkrementeller Sicherungen verbessert und von XenServer 7.3 und höher unterstützt wird. <br> <br> Normal: Nehmen Sie sich mehr Zeit für inkrementelle Sicherungen.",
    'UI_BACKUP_INC_MODE_CTB_TIPS' => "CBT：不保留任何快照,通过变化块跟踪技术计算有效数据",
    'UI_BACKUP_MODE_HIGH_SILENTSNAPSHOT' => "Stillgelegter Snapshot",
    'UI_BACKUP_MODE_HIGH_SILENTSNAPSHOT_TIPS' => "Indem Sie 'Quiesced Snapshot' aktivieren, um Dateisysteme oder Anwendungen auf der VM vor dem Erstellen des VM-Snapshots über Application-Awareness-Verarbeitung (z. B. VMware Tools) in einem konsistenten Zustand zu halten. <br> <br> Für die Unterstützung von Microsoft sind Anwendungen unter Windows erforderlich VSS. <br> <br> Wenn der stillgelegte Snapshot nicht erstellt werden konnte, erstellt das System einen Standardsnapshot. ",
